    border: "1px solid #e5e7eb",
};

const modalButtonRowStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "flex-end",
    gap: "0.75rem",
    flexWrap: "wrap",
};

const quickActionButtonStyle: React.CSSProperties = {
    padding: "0.5rem 0.75rem",
    borderRadius: "999px",
    border: "1px solid #bfd4c7",
    backgroundColor: "#ffffff",
    color: "#355447",
    cursor: "pointer",
    fontSize: "0.82rem",
    fontWeight: 700,
};

    const bookingDetailsListStyle: React.CSSProperties = {
      display: "grid",
      gap: "0.7rem",
    };

    const bookingDetailsCardStyle: React.CSSProperties = {
      border: "1px solid #e5e7eb",
      borderRadius: "0.8rem",
      padding: "0.75rem 0.85rem",
      backgroundColor: "#f8fafc",
    };

    const bookingDetailsTitleStyle: React.CSSProperties = {
      fontWeight: 800,
      color: "#163126",
      marginBottom: "0.3rem",
    };

    const bookingDetailsMetaStyle: React.CSSProperties = {
      fontSize: "0.9rem",
      color: "#374151",
      lineHeight: 1.45,
    };

    const bookingDetailsNoteStyle: React.CSSProperties = {
