    };

import { useEffect, useMemo, useState } from "react";
import type { Place, Booking } from "../types";
import { BookingList } from "./BookingList";
import { createBooking, deleteBooking, updatePlace, markNoShow, updateBooking } from "../services/api";
import { useViewport } from "../hooks/useViewport";

interface Props {
  place: Place | null;
  bookings: Booking[];
  onBookingCreated: () => void | Promise<void>;
  canEditPlaces: boolean;
  initialStartDate?: string;
  initialEndDate?: string;
  initialVehicleLengthM?: string;
  showBookingForm?: boolean;
  onBookingFinished?: () => void;
  focusedDateIso?: string | null;
  focusedBookingId?: number | null;
}

function formatDate(dateString: string) {
  const date = new Date(dateString);
  return date.toLocaleDateString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  });
}

function formatEuro(value: number) {
  return value.toLocaleString("de-DE", {
    style: "currency",
    currency: "EUR",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

function getMaxOccupancyInRange(
  bookings: Booking[],
  startDate: string,
  endDate: string
) {
  if (!startDate || !endDate || startDate >= endDate) {
    return 0;
  }

  const start = new Date(startDate);
  const end = new Date(endDate);

  let maxOccupancy = 0;

  for (
    let current = new Date(start);
    current < end;
    current.setDate(current.getDate() + 1)
  ) {
    const currentIso = current.toISOString().split("T")[0];

    const occupancy = bookings.filter(
      (booking) =>
        booking.start_date <= currentIso && currentIso < booking.end_date
    ).length;

    if (occupancy > maxOccupancy) {
      maxOccupancy = occupancy;
    }
  }

  return maxOccupancy;
}

function toIsoDate(date: Date) {
  return date.toISOString().split("T")[0];
}

function addDays(date: Date, days: number) {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

function getNights(startDate: string, endDate: string) {
  const start = new Date(`${startDate}T00:00:00`);
  const end = new Date(`${endDate}T00:00:00`);
  const msPerDay = 1000 * 60 * 60 * 24;
  return Math.max(0, Math.round((end.getTime() - start.getTime()) / msPerDay));
}

function getPlaceStatusLabel(
  isBlockedPlace: boolean,
  isPermanentPlace: boolean,
  isTentArea: boolean,
  currentOccupancy: number,
  capacity: number,
  isCurrentlyBooked: boolean
) {
  if (isBlockedPlace) return "Gesperrt";
  if (isPermanentPlace) return "Dauercamper";
  if (isTentArea) {
    if (currentOccupancy >= capacity) return "Voll";
    if (currentOccupancy > 0) return "Teilbelegt";
    return "Frei";
  }
  return isCurrentlyBooked ? "Belegt" : "Frei";
}

function getNextWeekendRange() {
  const today = new Date();
  const day = today.getDay(); // 0 = So, 1 = Mo, ..., 6 = Sa

  const daysUntilFriday = day <= 5 ? 5 - day : 6;
  const friday = addDays(today, daysUntilFriday);
  const sunday = addDays(friday, 2);

  friday.setHours(0, 0, 0, 0);
  sunday.setHours(0, 0, 0, 0);

  return {
    start: toIsoDate(friday),
    end: toIsoDate(sunday),
  };
}

function getNextWeekRange() {
  const today = new Date();
  const day = today.getDay(); // 0 = So
  const daysUntilNextMonday = day === 0 ? 1 : 8 - day;

  const monday = addDays(today, daysUntilNextMonday);
  const nextMonday = addDays(monday, 7);

  monday.setHours(0, 0, 0, 0);
  nextMonday.setHours(0, 0, 0, 0);

  return {
    start: toIsoDate(monday),
    end: toIsoDate(nextMonday),
  };
}

const PLACE_TYPE_OPTIONS = ["Stellplatz", "Dauercamper", "Zeltwiese", "Gesperrt"] as const;
const CUSTOM_PLACE_TYPE = "__custom__";

export function PlaceDetailPanel({ place, bookings, onBookingCreated, canEditPlaces, initialStartDate = "", initialEndDate = "", initialVehicleLengthM = "", onBookingFinished, showBookingForm = true, focusedDateIso = null, focusedBookingId = null, }: Props) {
  const { isMobile, isTablet } = useViewport();
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [bookingToDelete, setBookingToDelete] = useState<number | null>(null);
  const [editingBooking, setEditingBooking] = useState<Booking | null>(null);
  const [editGuestName, setEditGuestName] = useState("");
  const [editStartDate, setEditStartDate] = useState("");
  const [editEndDate, setEditEndDate] = useState("");
  const [editVehicleSize, setEditVehicleSize] = useState("");
  const [editNotes, setEditNotes] = useState("");
  const [editError, setEditError] = useState<string | null>(null);
  const [editSaving, setEditSaving] = useState(false);

  const [editName, setEditName] = useState("");
  const [editType, setEditType] = useState("");
  const [selectedTypeOption, setSelectedTypeOption] = useState<string>("Stellplatz");
  const [editCapacity, setEditCapacity] = useState(1);
  const [guestName, setGuestName] = useState("");
  const [vehicleLengthM, setVehicleLengthM] = useState("");
  const [notes, setNotes] = useState("");
  const [editLengthM, setEditLengthM] = useState("");
  const [editPricePerNight, setEditPricePerNight] = useState("");
  const [tentCount, setTentCount] = useState("1");

  useEffect(() => {
    if (place) {
      const currentType = place.type || "Stellplatz";

      setEditName(place.name);
      setEditType(currentType);
      setEditCapacity(place.capacity || 1);
      setEditLengthM(
      place.length_m !== null && place.length_m !== undefined
        ? String(place.length_m)
        : ""
    );
      setEditPricePerNight(
        place.price_per_night !== null && place.price_per_night !== undefined
          ? String(place.price_per_night).replace(".", ",")
          : "15,00"
      );

      if (PLACE_TYPE_OPTIONS.includes(currentType as (typeof PLACE_TYPE_OPTIONS)[number])) {
        setSelectedTypeOption(currentType);
      } else {
        setSelectedTypeOption(CUSTOM_PLACE_TYPE);
      }

      setErrorMessage(null);
        setStartDate(initialStartDate);
        setEndDate(initialEndDate);
        setGuestName("");

        setVehicleLengthM(
          currentType === "Zeltwiese" ? "" : initialVehicleLengthM
        );

        setNotes("");
    }
      }, [
      place,
      initialStartDate,
      initialEndDate,
      initialVehicleLengthM,
    ]);

  const today = new Date().toISOString().split("T")[0];

  const sortedBookings = useMemo(
    () => [...bookings].sort((a, b) => a.start_date.localeCompare(b.start_date)),
    [bookings]
  );

  const activeBookingsForFocusDate = useMemo(() => {
    if (!focusedDateIso) return [];
    return sortedBookings.filter(
      (booking) =>
        booking.start_date <= focusedDateIso && focusedDateIso < booking.end_date
    );
  }, [sortedBookings, focusedDateIso]);

  const focusedBookings = useMemo(() => {
    if (!focusedDateIso) return [];

    if (focusedBookingId !== null) {
      const exact = sortedBookings.find((booking) => booking.id === focusedBookingId);
      if (exact) {
        return [exact];
      }
    }

    return activeBookingsForFocusDate;
  }, [sortedBookings, focusedDateIso, focusedBookingId, activeBookingsForFocusDate]);

  const showFocusedBookingSection = focusedDateIso !== null && focusedBookings.length > 0;

  if (!place) {
    return (
      <div style={emptyStateStyle}>
        <div style={emptyIconStyle}>️</div>
        <h3 style={emptyTitleStyle}>Kein Platz ausgewählt</h3>
        <p style={emptyTextStyle}>
          Wähle links in der Liste oder direkt auf der Karte einen Platz aus, um Details,
          Buchungen und Bearbeitungsmöglichkeiten zu sehen.
        </p>
      </div>
    );
  }
  const currentPlace = place;
  const isCurrentlyBooked = bookings.some(
    (booking) => today >= booking.start_date && today < booking.end_date
  );

  const upcomingBookings = sortedBookings
    .filter((b) => b.start_date >= today)
    .sort((a, b) => a.start_date.localeCompare(b.start_date));

  const currentAndUpcomingBookings = sortedBookings.filter(
    (booking) => booking.end_date > today
  );

  const nextBooking = upcomingBookings[0] ?? null;

  const currentOccupancy = bookings
  .filter(
    (booking) =>
      today >= booking.start_date &&
      today < booking.end_date
  )
  .reduce((sum, booking) => {
    if (currentPlace.type === "Zeltwiese") {
      return sum + (booking.tent_count ?? 1);
    }

    return sum + 1;
  }, 0);

  const maxOccupancyInSelectedRange =
    startDate && endDate
      ? getMaxOccupancyInRange(bookings, startDate, endDate)
      : 0;

  const hasConflict = maxOccupancyInSelectedRange >= currentPlace.capacity;
  const isPermanentCamper = currentPlace.type === "Dauercamper";

  function applyQuickRange(start: string, end: string) {
      setStartDate(start);
      setEndDate(end);
      setErrorMessage(null);
    }

  async function handleSubmit() {
  if (!startDate || !endDate) {
    setErrorMessage("Bitte Start- und Enddatum auswählen.");
    return;
  }

  if (!guestName.trim()) {
    setErrorMessage("Bitte einen Namen eingeben.");
    return;
  }

  const parsedVehicleLength =
    vehicleLengthM.trim() === ""
      ? null
      : Number(vehicleLengthM.replace(",", "."));

  if (
  currentPlace.type !== "Zeltwiese" &&
  parsedVehicleLength !== null &&
  currentPlace.length_m !== null &&
  currentPlace.length_m !== undefined &&
  parsedVehicleLength > currentPlace.length_m
) {
    setErrorMessage(
      `Fahrzeug ist zu lang. Maximal ${currentPlace.length_m} m erlaubt.`
    );
    return;
  }

  try {
    setErrorMessage(null);

    await createBooking({
      place_id: currentPlace.id,
      start_date: startDate,
      end_date: endDate,
      guest_name: guestName,
      vehicle_size: vehicleLengthM
          ? currentPlace.type === "Zeltwiese"
            ? vehicleLengthM
            : `${vehicleLengthM} m`
          : "",
      tent_count:
          currentPlace.type === "Zeltwiese"
            ? Number(tentCount)
            : null,
      notes: notes,
    });

    await onBookingCreated();
    onBookingFinished?.();
    setStartDate("");
    setEndDate("");
    setGuestName("");
    setVehicleLengthM("");
    setNotes("");
  } catch (err: any) {
    setErrorMessage(err.message);
  }
}

  async function handleSavePlace() {
  try {
    setErrorMessage(null);

    const parsedPrice = Number(editPricePerNight.replace(",", "."));
    if (!Number.isFinite(parsedPrice) || parsedPrice < 0) {
      setErrorMessage("Bitte einen gültigen Preis pro Nacht eingeben.");
      return;
    }

    await updatePlace(currentPlace.id, {
      name: editName,
      type: editType,
      capacity: editCapacity,
      price_per_night: parsedPrice,
      length_m:
        editLengthM.trim() === ""
          ? null
          : Number(editLengthM.replace(",", ".")),
    });

    await onBookingCreated();
  } catch (err: any) {
    setErrorMessage(err.message);
  }
}

  function requestDeleteBooking(bookingId: number) {
    setBookingToDelete(bookingId);
  }

  async function confirmDeleteBooking() {
    if (bookingToDelete === null) return;

    try {
      setErrorMessage(null);
      await deleteBooking(bookingToDelete);
      setBookingToDelete(null);
      await onBookingCreated();
    } catch (err: any) {
      setErrorMessage(err.message);
    }
  }

  function cancelDeleteBooking() {
    setBookingToDelete(null);
  }

  function openEditBooking(booking: Booking) {
    setEditingBooking(booking);
    setEditGuestName(booking.guest_name);
    setEditStartDate(booking.start_date);
    setEditEndDate(booking.end_date);
    setEditVehicleSize(booking.vehicle_size || "");
    setEditNotes(booking.notes || "");
    setEditError(null);
  }

  function closeEditBooking() {
    setEditingBooking(null);
    setEditGuestName("");
    setEditStartDate("");
    setEditEndDate("");
    setEditVehicleSize("");
    setEditNotes("");
    setEditError(null);
  }

  async function handleSaveEditedBooking() {
    if (!editingBooking) return;

    if (!editGuestName.trim()) {
      setEditError("Bitte einen Gastnamen eingeben.");
      return;
    }

    if (!editStartDate || !editEndDate) {
      setEditError("Bitte Anreise und Abreise auswählen.");
      return;
    }

    if (editStartDate >= editEndDate) {
      setEditError("Die Abreise muss nach der Anreise liegen.");
      return;
    }

    try {
      setEditSaving(true);
      setEditError(null);

      await updateBooking(editingBooking.id, {
        place_id: editingBooking.place_id,
        start_date: editStartDate,
        end_date: editEndDate,
        guest_name: editGuestName.trim(),
        guest_street: editingBooking.guest_street || undefined,
        guest_postal_code: editingBooking.guest_postal_code || undefined,
        guest_city: editingBooking.guest_city || undefined,
        nationality: editingBooking.nationality || undefined,
        adult_count: editingBooking.adult_count ?? editingBooking.people_count ?? 1,
        child_count: editingBooking.child_count ?? 0,
        day_visitor_count: editingBooking.day_visitor_count ?? 0,
        has_electricity: Boolean(editingBooking.has_electricity),
        has_waste: Boolean(editingBooking.has_waste),
        has_rhine_view: Boolean(editingBooking.has_rhine_view),
        dog_count: editingBooking.dog_count ?? 0,
        car_count: editingBooking.car_count ?? 0,
        motorcycle_count: editingBooking.motorcycle_count ?? 0,
        camper_count: editingBooking.camper_count ?? 0,
        camper_length_m: editingBooking.camper_length_m ?? null,
        tent_tariff_code: editingBooking.tent_tariff_code ?? null,
        place_price_per_night: editingBooking.place_price_per_night ?? currentPlace.price_per_night ?? 15,
        vehicle_size: editVehicleSize,
        tent_count: editingBooking.tent_count ?? null,
        notes: editNotes,
      });

      await onBookingCreated();
      closeEditBooking();
    } catch (err: any) {
      setEditError(err.message || "Fehler beim Bearbeiten der Buchung");
    } finally {
      setEditSaving(false);
    }
  }
  const isBlockedPlace = currentPlace.type === "Gesperrt";
  const isPermanentPlace = currentPlace.type === "Dauercamper";
  const isTentArea = currentPlace.type === "Zeltwiese";

const isTentAreaPartiallyOccupied =
  isTentArea &&
  currentOccupancy > 0 &&
  currentOccupancy < currentPlace.capacity;

const isTentAreaFull =
  isTentArea &&
  currentOccupancy >= currentPlace.capacity;

  return (
      <div style={{display: "flex", flexDirection: "column", gap: "1rem"}}>
          <section
            style={{
              ...heroSectionStyle,
              flexDirection: isMobile ? "column" : heroSectionStyle.flexDirection,
              alignItems: isMobile ? "stretch" : heroSectionStyle.alignItems,
            }}
          >
              <div style={heroLeftStyle}>
                  <div style={eyebrowStyle}>Ausgewählter Platz</div>

                  <h2 style={heroTitleStyle}>Platz {currentPlace.name}</h2>

                  <div style={metaRowStyle}>
      <span style={metaBadgeStyle}>
        {currentPlace.type || "Stellplatz"}
      </span>

                      <span style={metaBadgeStyle}>
        Kapazität {currentPlace.capacity}
      </span>

                      <span style={metaBadgeStyle}>
         {currentPlace.length_m ? `${currentPlace.length_m} m` : "nicht gesetzt"}
      </span>

                      <span style={metaBadgeStyle}>
         {formatEuro(currentPlace.price_per_night ?? 15)}
      </span>
                  </div>
              </div>

              <div
                  style={{
                      ...statusPillStyle,
                      width: isMobile ? "100%" : "auto",

                      backgroundColor: isBlockedPlace
                          ? "#fef3c7"
                          : isPermanentPlace
                              ? "#e5e7eb"
                              : isTentAreaFull
                                  ? "#fee2e2"
                                  : isTentAreaPartiallyOccupied
                                      ? "#fef3c7"
                                      : isCurrentlyBooked
                                          ? "#fee2e2"
                                          : "#dcfce7",

                      color: isBlockedPlace
                          ? "#92400e"
                          : isPermanentPlace
                              ? "#374151"
                              : isTentAreaFull
                                  ? "#991b1b"
                                  : isTentAreaPartiallyOccupied
                                      ? "#92400e"
                                      : isCurrentlyBooked
                                          ? "#991b1b"
                                          : "#166534",

                      borderColor: isBlockedPlace
                          ? "#fde68a"
                          : isPermanentPlace
                              ? "#d1d5db"
                              : isTentAreaFull
                                  ? "#fecaca"
                                  : isTentAreaPartiallyOccupied
                                      ? "#fde68a"
                                      : isCurrentlyBooked
                                          ? "#fecaca"
                                          : "#bbf7d0",
                  }}
              >
                  {isBlockedPlace
                      ? " Gesperrt"
                      : isPermanentPlace
                          ? "⚫ Dauercamper"
                          : isTentAreaFull
                              ? ` Voll belegt (${currentOccupancy}/${currentPlace.capacity} Zelte)`
                              : isTentAreaPartiallyOccupied
                                  ? ` Teilbelegt (${currentOccupancy}/${currentPlace.capacity} Zelte)`
                                  : isTentArea
                                      ? ` Frei (0/${currentPlace.capacity} Zelte)`
                                      : isCurrentlyBooked
                                          ? " Aktuell belegt"
                                          : " Aktuell frei"}
              </div>
          </section>
        {showBookingForm && (
          <section style={panelStyle}>
              <div style={sectionHeaderStyle}>
                  <div>
                      <h3 style={sectionTitleStyle}>Neue Buchung</h3>
                      <p style={sectionSubtitleStyle}>
                          Gastdaten und Zeitraum für eine neue Belegung erfassen.
                      </p>
                  </div>
              </div>
              <div style={quickActionWrapperStyle}>
                  <div style={quickActionLabelStyle}>Schnellauswahl</div>

                  <div
                    style={{
                      ...quickActionRowStyle,
                      flexDirection: isMobile ? "column" : quickActionRowStyle.flexDirection,
                    }}
                  >
                      <button
                          type="button"
                          onClick={() => {
                              const today = new Date();
                              const tomorrow = addDays(today, 1);
                              applyQuickRange(toIsoDate(today), toIsoDate(tomorrow));
                          }}
                          style={quickActionButtonStyle}
                      >
                          Heute → morgen
                      </button>

                      <button
                          type="button"
                          onClick={() => {
                              const today = new Date();
                              const nextWeek = addDays(today, 7);
                              applyQuickRange(toIsoDate(today), toIsoDate(nextWeek));
                          }}
                          style={quickActionButtonStyle}
                      >
                          Heute → 7 Tage
                      </button>

                      <button
                          type="button"
                          onClick={() => {
                              const range = getNextWeekendRange();
                              applyQuickRange(range.start, range.end);
                          }}
                          style={quickActionButtonStyle}
                      >
                          Wochenende
                      </button>

                      <button
                          type="button"
                          onClick={() => {
                              const range = getNextWeekRange();
                              applyQuickRange(range.start, range.end);
                          }}
                          style={quickActionButtonStyle}
                      >
                          Nächste Woche
                      </button>
                  </div>
              </div>

              <div
                style={{
                  ...formGridWideStyle,
                  gridTemplateColumns: isMobile
                    ? "1fr"
                    : isTablet
                      ? "repeat(2, minmax(0, 1fr))"
                      : formGridWideStyle.gridTemplateColumns,
                }}
              >
                  <div>
                      <label style={labelStyle}>Name</label>
                      <input
                          value={guestName}
                          onChange={(e) => setGuestName(e.target.value)}
                          style={inputStyle}
                      />
                  </div>

                  <div>
                        <label style={labelStyle}>
                            {currentPlace.type === "Zeltwiese"
                                ? "⛺ Zeltgröße"
                                : " Fahrzeuglänge in m"}
                        </label>

                        <input
                            type="text"
                            inputMode={currentPlace.type === "Zeltwiese" ? "text" : "decimal"}
                            value={vehicleLengthM}
                            onChange={(e) => setVehicleLengthM(e.target.value)}
                            placeholder={
                                currentPlace.type === "Zeltwiese"
                                    ? "z.B. Familienzelt / 4x3 m"
                                    : "z.B. 7,5"
                            }
                            style={inputStyle}
                        />
                    </div>

                    {currentPlace.type === "Zeltwiese" && (
                      <div>
                        <label style={labelStyle}>️ Anzahl Zelte</label>

                        <input
                          type="number"
                          min="1"
                          step="1"
                          value={tentCount}
                          onChange={(e) => setTentCount(e.target.value)}
                          style={inputStyle}
                        />
                      </div>
                    )}

                  <div style={{gridColumn: "1 / -1"}}>
                      <label style={labelStyle}>Weitere Informationen</label>
                      <input
                          value={notes}
                          onChange={(e) => setNotes(e.target.value)}
                          style={inputStyle}
                      />
                  </div>

                  <div>
                      <label style={labelStyle}>Von</label>
                      <input
                          type="date"
                          value={startDate}
                          onChange={(e) => setStartDate(e.target.value)}
                          style={inputStyle}
                      />
                  </div>

                  <div>
                      <label style={labelStyle}>Bis</label>
                      <input
                          type="date"
                          value={endDate}
                          onChange={(e) => setEndDate(e.target.value)}
                          style={inputStyle}
                      />
                  </div>

                  <div style={buttonFieldStyle}>
                      <button
                          onClick={handleSubmit}
                          disabled={
                              !startDate || !endDate || !guestName.trim() || hasConflict || isPermanentCamper
                          }
                          style={{
                              ...primaryButtonStyle,
                              opacity:
                                  !startDate || !endDate || !guestName.trim() || hasConflict || isPermanentCamper
                                      ? 0.6
                                      : 1,
                              cursor:
                                  !startDate || !endDate || !guestName.trim() || hasConflict || isPermanentCamper
                                      ? "not-allowed"
                                      : "pointer",
                          }}
                      >
                          Buchung anlegen
                      </button>
                  </div>
              </div>

              {startDate && endDate && (
                  <div
                      style={{
                          ...infoBoxStyle,
                          backgroundColor: hasConflict ? "#fee2e2" : "#dcfce7",
                          color: hasConflict ? "#991b1b" : "#166534",
                          borderColor: hasConflict ? "#fecaca" : "#bbf7d0",
                      }}
                  >
                      {hasConflict
                          ? `⚠️ Zeitraum an mindestens einem Tag voll belegt (${maxOccupancyInSelectedRange}/${currentPlace.capacity})`
                          : `✅ Zeitraum verfügbar (max. ${maxOccupancyInSelectedRange}/${currentPlace.capacity} gleichzeitig belegt)`}
                  </div>
              )}

              {isPermanentCamper && (
                  <div
                      style={{
                          ...infoBoxStyle,
                          backgroundColor: "#f3f4f6",
                          color: "#374151",
                          borderColor: "#e5e7eb",
                      }}
                  >
                      Dieser Platz ist als Dauercamper markiert und kann nicht gebucht werden.
                  </div>
              )}

              {errorMessage && (
                  <div
                      style={{
                          ...infoBoxStyle,
                          backgroundColor: "#fee2e2",
                          color: "#991b1b",
                          borderColor: "#fecaca",
                      }}
                  >
                      {errorMessage}
                  </div>
              )}
          </section>
          )}

          <section
            style={{
              ...statsGridStyle,
              gridTemplateColumns: isMobile
                ? "1fr"
                : isTablet
                  ? "repeat(2, minmax(0, 1fr))"
                  : statsGridStyle.gridTemplateColumns,
            }}
          >
              <div style={statCardStyle}>
                  <div style={statLabelStyle}>
                      {isTentArea ? "Aktuelle Zeltbelegung" : "Aktuelle Belegung"}
                  </div>
                  <div style={statValueStyle}>
                      {currentOccupancy} / {currentPlace.capacity}
                  </div>
                  <div style={statHelpStyle}>
                      {isTentArea
                          ? "aktuell belegte Zelte"
                          : "gleichzeitig belegte Einheiten heute"}
                  </div>
              </div>

              <div style={statCardStyle}>
                  <div style={statLabelStyle}>Gebucht ab</div>
                  <div style={statValueStyleSmall}>
                      {nextBooking ? formatDate(nextBooking.start_date) : "—"}
                  </div>
                  <div style={statHelpStyle}>
                      {nextBooking ? "nächster Belegungsbeginn" : "keine zukünftige Buchung"}
                  </div>
              </div>

              <div style={statCardStyle}>
                  <div style={statLabelStyle}>Frei ab</div>
                  <div style={statValueStyleSmall}>
                      {nextBooking ? formatDate(nextBooking.end_date) : "—"}
                  </div>
                  <div style={statHelpStyle}>
                      {nextBooking ? "wieder verfügbar ab" : "aktuell nichts geplant"}
                  </div>
              </div>
          </section>
          {showFocusedBookingSection && (
            <section style={panelStyle}>
              <div style={sectionHeaderStyle}>
                <h3 style={sectionTitleStyle}>Buchungsinformationen</h3>
                <p style={sectionSubtitleStyle}>
                  Status: {getPlaceStatusLabel(
                    isBlockedPlace,
                    isPermanentPlace,
                    isTentArea,
                    currentOccupancy,
                    currentPlace.capacity,
                    isCurrentlyBooked
                  )}
                </p>
                <p style={sectionSubtitleStyle}>Datum: {formatDate(focusedDateIso)}</p>
                {isTentArea && (
                  <p style={sectionSubtitleStyle}>
                    Belegung: {currentOccupancy} / {currentPlace.capacity}
                  </p>
                )}
              </div>

              <div style={bookingDetailsListStyle}>
                {focusedBookings.map((booking) => (
                  <article key={booking.id} style={bookingDetailsCardStyle}>
                    <div style={bookingDetailsTitleStyle}>{booking.guest_name}</div>
                    <div style={bookingDetailsMetaStyle}>
                      {formatDate(booking.start_date)} - {formatDate(booking.end_date)}
                      {` (${getNights(booking.start_date, booking.end_date)} ${getNights(booking.start_date, booking.end_date) === 1 ? "Übernachtung" : "Übernachtungen"})`}
                    </div>
                    {booking.nationality && (
                      <div style={bookingDetailsMetaStyle}>Land: {booking.nationality}</div>
                    )}
                    {booking.vehicle_size && (
                      <div style={bookingDetailsMetaStyle}>Fahrzeug: {booking.vehicle_size}</div>
                    )}
                    {booking.camper_length_m !== null && booking.camper_length_m !== undefined && (
                      <div style={bookingDetailsMetaStyle}>
                        Fahrzeuglänge: {String(booking.camper_length_m).replace(".", ",")} m
                      </div>
                    )}
                    {(booking.adult_count || booking.people_count || booking.child_count) && (
                      <div style={bookingDetailsMetaStyle}>
                        Personen: {booking.adult_count ?? booking.people_count ?? 0}
                        {booking.child_count ? ` + ${booking.child_count} Kinder` : ""}
                      </div>
                    )}
                    {booking.notes && (
                      <div style={bookingDetailsNoteStyle}>Notizen: {booking.notes}</div>
                    )}
                  </article>
                ))}
              </div>
            </section>
          )}
          <section style={panelStyle}>
              <div style={sectionHeaderStyle}>
                  <div>
                      <h3 style={sectionTitleStyle}>Buchungen</h3>
                      <p style={sectionSubtitleStyle}>
                          Aktuelle und zukünftige Buchungen für Platz {currentPlace.name}.
                      </p>
                  </div>
              </div>

              <BookingList
                bookings={currentAndUpcomingBookings}
                onDelete={requestDeleteBooking}
                onEdit={openEditBooking}
              />
          </section>

          {canEditPlaces && (
              <section style={panelStyle}>
                  <div style={sectionHeaderStyle}>
                      <div>
                          <h3 style={sectionTitleStyle}>Platz bearbeiten</h3>
                          <p style={sectionSubtitleStyle}>
                              Name, Typ und Kapazität des Platzes anpassen.
                          </p>
                      </div>
                  </div>

                  <div
                    style={{
                      ...formGridStyle,
                      gridTemplateColumns: isMobile
                        ? "1fr"
                        : isTablet
                          ? "repeat(2, minmax(0, 1fr))"
                          : formGridStyle.gridTemplateColumns,
                    }}
                  >
                      <div>
                          <label style={labelStyle}>Name / Nummer</label>
                          <input
                              value={editName}
                              onChange={(e) => setEditName(e.target.value)}
                              style={inputStyle}
                          />
                      </div>

                      <div>
                          <label style={labelStyle}>Typ</label>
                          <select
                              value={selectedTypeOption}
                              onChange={(e) => {
                                  const value = e.target.value;
                                  setSelectedTypeOption(value);

                                  if (value !== CUSTOM_PLACE_TYPE) {
                                      setEditType(value);
                                  } else {
                                      setEditType("");
                                  }
                              }}
                              style={inputStyle}
                          >
                              {PLACE_TYPE_OPTIONS.map((option) => (
                                  <option key={option} value={option}>
                                      {option}
                                  </option>
                              ))}
                              <option value={CUSTOM_PLACE_TYPE}>Anderer Typ...</option>
                          </select>

                          {selectedTypeOption === CUSTOM_PLACE_TYPE && (
                              <input
                                  value={editType}
                                  onChange={(e) => setEditType(e.target.value)}
                                  placeholder="Eigenen Typ eingeben"
                                  style={{...inputStyle, marginTop: "0.6rem"}}
                              />
                          )}
                      </div>

                      <div>
                          <label style={labelStyle}>Kapazität</label>
                          <input
                              type="number"
                              min="1"
                              value={editCapacity}
                              onChange={(e) => setEditCapacity(Number(e.target.value))}
                              style={inputStyle}
                          />
                      </div>
                      <div>
                          <label style={labelStyle}>Platzlänge in m</label>
                          <input
                              type="text"
                              inputMode="decimal"
                              value={editLengthM}
                              onChange={(e) => setEditLengthM(e.target.value)}
                              placeholder="z.B. 8,5"
                              style={inputStyle}
                          />
                      </div>
                      <div>
                          <label style={labelStyle}>Preis pro Nacht (EUR)</label>
                          <input
                              type="text"
                              inputMode="decimal"
                              value={editPricePerNight}
                              onChange={(e) => setEditPricePerNight(e.target.value)}
                              placeholder="z.B. 15,00"
                              style={inputStyle}
                          />
                      </div>
                      <div style={buttonFieldStyle}>
                          <button onClick={handleSavePlace} style={primaryButtonStyle}>
                              Änderungen speichern
                          </button>
                      </div>
                  </div>
              </section>
          )}

          {editingBooking && (
            <div style={modalOverlayStyle}>
              <div style={modalCardStyle}>
                <h3 style={{ marginTop: 0, marginBottom: "0.75rem", color: "#163126" }}>
                  Buchung bearbeiten
                </h3>

                <div style={{ display: "grid", gap: "0.65rem" }}>
                  <div>
                    <label style={labelStyle}>Gastname</label>
                    <input
                      value={editGuestName}
                      onChange={(e) => setEditGuestName(e.target.value)}
                      style={inputStyle}
                    />
                  </div>

                  <div>
                    <label style={labelStyle}>Anreise</label>
                    <input
                      type="date"
                      value={editStartDate}
                      onChange={(e) => setEditStartDate(e.target.value)}
                      style={inputStyle}
                    />
                  </div>

                  <div>
                    <label style={labelStyle}>Abreise</label>
                    <input
                      type="date"
                      value={editEndDate}
                      onChange={(e) => setEditEndDate(e.target.value)}
                      style={inputStyle}
                    />
                  </div>

                  <div>
                    <label style={labelStyle}>Fahrzeug</label>
                    <input
                      value={editVehicleSize}
                      onChange={(e) => setEditVehicleSize(e.target.value)}
                      style={inputStyle}
                    />
                  </div>

                  <div>
                    <label style={labelStyle}>Notizen</label>
                    <input
                      value={editNotes}
                      onChange={(e) => setEditNotes(e.target.value)}
                      style={inputStyle}
                    />
                  </div>
                </div>

                {editError && (
                  <div
                    style={{
                      ...infoBoxStyle,
                      backgroundColor: "#fee2e2",
                      color: "#991b1b",
                      borderColor: "#fecaca",
                    }}
                  >
                    {editError}
                  </div>
                )}

                <div style={modalButtonRowStyle}>
                  <button onClick={closeEditBooking} style={secondaryButtonStyle} disabled={editSaving}>
                    Abbrechen
                  </button>
                  <button
                    onClick={handleSaveEditedBooking}
                    style={primaryButtonStyle}
                    disabled={editSaving}
                  >
                    {editSaving ? "Speichert ..." : "Speichern"}
                  </button>
                </div>
              </div>
            </div>
          )}

          {bookingToDelete !== null && (
              <div style={modalOverlayStyle}>
                  <div style={modalCardStyle}>
                      <h3 style={{marginTop: 0, marginBottom: "0.75rem", color: "#163126"}}>
                          Buchung stornieren
                      </h3>

                      <p style={{marginBottom: "1rem", color: "#4b5563", lineHeight: 1.5}}>
                          Möchtest du diese Buchung wirklich stornieren?
                      </p>

                      <div style={modalButtonRowStyle}>
                          <button onClick={cancelDeleteBooking} style={secondaryButtonStyle}>
                              Abbrechen
                          </button>

                          <button
                              onClick={confirmDeleteBooking}
                              style={{
                                  ...dangerButtonStyle,
                                  backgroundColor: "#dc2626",
                                  borderColor: "#dc2626",
                              }}
                          >
                              Stornieren
                          </button>
                          <button
                              onClick={async () => {
                                  if (bookingToDelete === null) return;

                                  await markNoShow(bookingToDelete);
                                  setBookingToDelete(null);
                                  await onBookingCreated();
                              }}
                              style={{
                                  background: "#f59e0b",
                                  color: "white",
                                  borderRadius: "6px",
                                  padding: "6px 10px",
                                  border: "none",
                                  cursor: "pointer",
                              }}
                          >
                              Nicht erschienen
                          </button>

                      </div>
                  </div>
              </div>
          )}
      </div>
  );
}

